const courses=[
{id:'tarot',name:'Tarot nhập môn',cat:'Bài trực giác',icon:'☾',color:'linear-gradient(135deg,#51405a,#241b32)',desc:'Bắt đầu hành trình khám phá bộ bài Tarot và ngôn ngữ biểu tượng.',level:'Cơ bản',lessons:[['Làm quen với Tarot','Tarot là một bộ bài gồm 78 lá, thường được dùng như công cụ chiêm nghiệm thông qua hình ảnh và biểu tượng. Một bộ bài có 22 lá Ẩn chính và 56 lá Ẩn phụ.','Hãy xem mỗi lá bài như một câu hỏi mở, không phải lời tiên đoán chắc chắn. Bắt đầu bằng việc quan sát nhân vật, màu sắc và cảm xúc mà hình ảnh gợi lên.'],['22 lá Ẩn chính','Ẩn chính mô tả những chủ đề lớn trong hành trình trải nghiệm của con người. Ví dụ, The Fool gợi sự khởi đầu và tinh thần khám phá; The Hermit gợi sự lắng lại để tìm kiếm nội tâm.','Ý nghĩa một lá thay đổi theo câu hỏi, vị trí và bối cảnh. Tránh học thuộc một từ khóa rồi áp dụng máy móc.'],['56 lá Ẩn phụ','Ẩn phụ gồm bốn chất: Gậy thường gắn với hành động, Cốc với cảm xúc, Kiếm với tư duy và Xu với đời sống vật chất. Mỗi chất có mười lá số và bốn lá hoàng gia.','Thử liên hệ số, chất và hình ảnh: Ace có thể là một khởi đầu; Ten thường gợi một chu kỳ đã phát triển đầy đủ.'],['Trải bài ba lá','Trải ba lá là một cách đơn giản để tổ chức suy nghĩ. Bạn có thể đặt vị trí là quá khứ, hiện tại, hướng phát triển hoặc tình huống, trở ngại, gợi ý.','Đặt câu hỏi mở, xào bài theo cách bạn thấy thoải mái và ghi lại những liên tưởng trước khi tra cứu. Hãy tổng hợp câu chuyện thay vì đọc từng lá tách rời.']],question:'Một bộ Tarot tiêu chuẩn có bao nhiêu lá?',options:['36 lá','52 lá','78 lá','108 lá'],answer:2,explain:'Tarot tiêu chuẩn có 78 lá: 22 Ẩn chính và 56 Ẩn phụ.'},
{id:'lenormand',name:'Lenormand căn bản',cat:'Bài trực giác',icon:'⚜',color:'linear-gradient(135deg,#684d4c,#302832)',desc:'Đọc những biểu tượng gần gũi và kết nối chúng thành câu chuyện.',level:'Cơ bản',lessons:[['Giới thiệu Lenormand','Lenormand thường gồm 36 lá với các hình ảnh đời thường như Kỵ sĩ, Cỏ ba lá và Ngôi nhà. Lối đọc thường chú trọng sự kết hợp giữa các lá.','Một biểu tượng có thể được hiểu khác nhau theo câu hỏi; hãy ghi chép để nhận ra cách bạn diễn giải.'],['Ngôn ngữ biểu tượng','Ngôi nhà có thể gợi gia đình hoặc không gian quen thuộc; Con đường có thể gợi lựa chọn. Những liên tưởng này chỉ là điểm xuất phát.','Tránh gán ý nghĩa cứng nhắc. Tìm mối liên hệ giữa biểu tượng và hoàn cảnh thực tế.'],['Đọc cặp bài','Khi đọc hai lá, hãy xem lá đầu như chủ đề và lá sau bổ nghĩa, sau đó thử đảo cách hiểu. Ví dụ Ngôi nhà + Con đường có thể gợi lựa chọn liên quan đến nhà.','Viết ít nhất hai cách diễn giải và tự hỏi cách nào phù hợp với câu hỏi nhất.'],['Trải ba lá','Ba lá có thể tạo thành một câu ngắn: chủ đề, điều ảnh hưởng, hướng suy ngẫm. Không cần xem trải bài là kết luận cố định.','Đặt một câu hỏi cụ thể, ghép các biểu tượng, rồi kiểm tra giả định bằng thông tin thực tế.']],question:'Bộ Lenormand truyền thống thường có bao nhiêu lá?',options:['22 lá','36 lá','52 lá','78 lá'],answer:1,explain:'Bộ Lenormand thường có 36 lá.'},
{id:'oracle',name:'Oracle & trực giác',cat:'Bài trực giác',icon:'✧',color:'linear-gradient(135deg,#66516b,#312633)',desc:'Lắng nghe nội tâm qua những thông điệp và hình ảnh chữa lành.',level:'Cơ bản',lessons:[['Oracle là gì?','Oracle là tên chung cho những bộ bài thông điệp có cấu trúc linh hoạt. Khác Tarot, mỗi bộ có số lá và chủ đề do tác giả lựa chọn.','Đọc lời hướng dẫn của bộ bài, quan sát hình ảnh và ghi lại cảm nhận cá nhân.'],['Chọn bộ bài phù hợp','Hãy chọn bộ bài có hình ảnh, ngôn ngữ và cách diễn giải mà bạn thấy dễ tiếp cận. Bạn không cần nhiều bộ để bắt đầu.','Ưu tiên nguồn gốc rõ ràng và tôn trọng bản quyền của tác giả.'],['Đặt câu hỏi mở','Một câu hỏi hữu ích thường hướng tới điều bạn có thể suy ngẫm hoặc thực hiện, ví dụ: Tôi cần chú ý điều gì khi chuẩn bị cho cuộc trò chuyện?','Tránh dùng bài thay thế lời khuyên y tế, pháp lý hoặc tài chính chuyên môn.'],['Thực hành một lá','Rút một lá, ghi ba chi tiết bạn nhìn thấy, cảm xúc xuất hiện và một hành động nhỏ có thể làm.','Sau vài ngày, xem lại ghi chú để nhận biết bài học và cả những giả định chưa đúng.']],question:'Điểm nào thường đúng với bài Oracle?',options:['Luôn có đúng 78 lá','Cấu trúc linh hoạt tùy bộ bài','Chỉ dùng để dự đoán tương lai','Luôn có đúng 36 lá'],answer:1,explain:'Mỗi bộ Oracle có cấu trúc, số lá và chủ đề riêng.'},
{id:'bai-tay',name:'Giải mã bài Tây',cat:'Bài trực giác',icon:'♠',color:'linear-gradient(135deg,#5b414e,#242033)',desc:'Tìm hiểu 52 lá bài và những cách liên kết ý nghĩa cơ bản.',level:'Cơ bản',lessons:[['Cấu trúc bộ bài Tây','Bộ bài Tây tiêu chuẩn có 52 lá, chia thành bốn chất: cơ, rô, chuồn và bích. Mỗi chất gồm các lá từ Át đến K.','Một số bộ có thêm Joker; hãy thống nhất có sử dụng lá này trước khi thực hành.'],['Bốn chất bài','Trong một số truyền thống, cơ liên hệ cảm xúc, rô với nguồn lực, chuồn với hành động và bích với thử thách hoặc suy nghĩ. Các quy ước khác nhau giữa các hệ.','Hãy ghi rõ hệ quy chiếu đang dùng thay vì cho rằng một nghĩa là duy nhất.'],['Số và lá hình','Các lá số có thể được đọc theo tiến trình từ khởi đầu đến hoàn tất; J, Q và K thường gợi vai trò, phẩm chất hoặc nhân vật.','Kết hợp số, chất và câu hỏi để tạo cách hiểu có bối cảnh.'],['Thực hành ba lá','Chọn ba lá và đặt cho mỗi vị trí một vai trò: bối cảnh, điều cần cân nhắc và hành động nhỏ.','Ghi nhận cả cách hiểu thay thế, không dùng kết quả làm căn cứ duy nhất cho quyết định quan trọng.']],question:'Bộ bài Tây tiêu chuẩn, không tính Joker, có bao nhiêu lá?',options:['36','52','56','78'],answer:1,explain:'Bộ bài Tây tiêu chuẩn gồm 52 lá, chia làm bốn chất.'},
{id:'tu-vi',name:'Tử vi nhập môn',cat:'Chiêm nghiệm',icon:'☯',color:'linear-gradient(135deg,#74533e,#33252a)',desc:'Khám phá cấu trúc lá số và nền tảng tư duy phương Đông.',level:'Cơ bản',lessons:[['Tử vi là gì?','Tử vi Đẩu số là một hệ thống diễn giải truyền thống sử dụng thông tin sinh để lập lá số gồm các cung và sao. Có nhiều trường phái và cách an sao khác nhau.','Nên tiếp cận như di sản văn hóa và công cụ chiêm nghiệm, không phải kết luận khoa học về số phận.'],['Mười hai cung','Một lá số thường có 12 cung biểu thị các lĩnh vực đời sống, như Mệnh, Phụ Mẫu, Phúc Đức và Quan Lộc. Cần đọc trong tổng thể thay vì tách một cung.','Khi học, hãy làm quen tên gọi và chức năng của từng cung trước khi luận đoán.'],['Sao và bố cục','Các sao là thành phần biểu tượng được an vào cung theo quy tắc của từng hệ. Ý nghĩa phụ thuộc vào vị trí, tổ hợp và trường phái.','Đừng kết luận về một người chỉ từ một sao; so sánh nhiều nguồn và ghi rõ phương pháp.'],['Thực hành đọc cấu trúc','Lấy một lá số mẫu đã ẩn thông tin cá nhân, xác định tên 12 cung và tìm cung Mệnh. Chưa cần đưa ra dự đoán.','Kiểm tra múi giờ, lịch âm dương và giờ sinh trước khi lập lá số; sai dữ liệu có thể làm thay đổi kết quả.']],question:'Một lá số Tử vi thường có bao nhiêu cung?',options:['8','10','12','24'],answer:2,explain:'Lá số Tử vi thường được chia thành 12 cung.'},
{id:'tuong-so',name:'Tướng số & quan sát',cat:'Chiêm nghiệm',icon:'✺',color:'linear-gradient(135deg,#65504a,#2b252d)',desc:'Tiếp cận nhân tướng học như một hệ biểu tượng văn hóa.',level:'Khám phá',lessons:[['Tìm hiểu tướng số','Nhân tướng học là tập hợp các quan niệm truyền thống liên hệ đặc điểm ngoại hình với tính cách hoặc vận mệnh. Những liên hệ này không được xác lập như phương pháp đánh giá đáng tin cậy.','Không phán xét năng lực, đạo đức hay giá trị của ai dựa vào ngoại hình.'],['Bối cảnh văn hóa','Các cách xem tướng khác nhau theo thời gian, vùng miền và tài liệu. Nghiên cứu bối cảnh giúp phân biệt biểu tượng văn hóa với sự thật kiểm chứng được.','Khi đọc một nhận định, hãy hỏi: nguồn nào, bối cảnh nào và có bằng chứng gì?'],['Nhận diện thiên kiến','Thiên kiến xác nhận khiến ta dễ nhớ ví dụ phù hợp với niềm tin và bỏ qua trường hợp trái ngược. Hiệu ứng Barnum khiến mô tả chung chung có vẻ rất đúng với cá nhân.','Tập viết một phản ví dụ cho mỗi nhận định bạn gặp.'],['Quan sát có trách nhiệm','Quan sát để hiểu giao tiếp không đồng nghĩa với gán tính cách cố định. Hãy tôn trọng sự đồng thuận và quyền riêng tư.','Thực hành: chuyển câu “người có đặc điểm X thì tính cách Y” thành một câu hỏi trung lập, không phán xét.']],question:'Cách tiếp cận nào có trách nhiệm khi học tướng số?',options:['Đánh giá đạo đức qua ngoại hình','Coi mọi nhận định là chắc chắn','Xem xét bối cảnh và tránh phán xét','Dùng để tuyển dụng'],answer:2,explain:'Tôn trọng con người, bối cảnh và bằng chứng; không đánh giá con người qua ngoại hình.'},
{id:'kinh-dich',name:'Kinh Dịch nền tảng',cat:'Chiêm nghiệm',icon:'☷',color:'linear-gradient(135deg,#6a533a,#2f2829)',desc:'Làm quen âm dương, bát quái và tư duy về sự biến đổi.',level:'Cơ bản',lessons:[['Nhập môn Kinh Dịch','Kinh Dịch là tác phẩm kinh điển Trung Hoa liên quan đến biến đổi, biểu tượng và triết học. Một hệ thống phổ biến gồm 64 quẻ, mỗi quẻ có sáu hào.','Có thể học Kinh Dịch từ góc độ văn bản, lịch sử và chiêm nghiệm thay vì xem là công cụ dự đoán chắc chắn.'],['Âm dương và hào','Hào dương thường được biểu diễn bằng một nét liền; hào âm bằng nét đứt. Ba hào tạo thành một quái.','Âm dương là cặp khái niệm tương quan, không đơn giản tương ứng với tốt và xấu.'],['Bát quái và 64 quẻ','Bát quái là tám tổ hợp của ba hào. Ghép hai quái tạo thành một quẻ sáu hào, có tổng cộng 64 tổ hợp.','Thử đếm số tổ hợp: mỗi hào có hai trạng thái, vậy sáu hào tạo ra 2 mũ 6 tổ hợp.'],['Đọc quẻ có bối cảnh','Khi tham khảo một quẻ, hãy đọc bản dịch và chú giải, chú ý khác biệt giữa các nguồn. Kết nối ý nghĩa với câu hỏi mở và hoàn cảnh thực tế.','Ghi lại điều bạn học được và kiểm chứng quyết định bằng thông tin thực tế.']],question:'Một quẻ trong Kinh Dịch có bao nhiêu hào?',options:['3','4','6','8'],answer:2,explain:'Một quẻ có sáu hào; 64 quẻ tương ứng 64 tổ hợp.'},
{id:'bua-chu',name:'Nghi thức & biểu tượng',cat:'Nghi thức',icon:'✵',color:'linear-gradient(135deg,#59445d,#272031)',desc:'Tìm hiểu bùa chú và nghi thức từ góc nhìn văn hóa, an toàn.',level:'Khám phá',lessons:[['Nghi thức trong văn hóa','Bùa chú và nghi thức xuất hiện trong nhiều truyền thống với ý nghĩa biểu tượng, cộng đồng và niềm tin khác nhau. Không có bằng chứng đảm bảo hiệu lực siêu nhiên.','Tôn trọng nguồn gốc văn hóa; tránh thương mại hóa hoặc sử dụng biểu tượng thiêng một cách thiếu hiểu biết.'],['Ý định và biểu tượng','Một nghi thức cá nhân đơn giản có thể là dành vài phút tĩnh lặng, viết mục tiêu và lựa chọn một biểu tượng nhắc nhở bản thân.','Biểu tượng không thay thế hành động thực tế hay hỗ trợ chuyên môn.'],['An toàn khi thực hành','Không uống, đốt hoặc bôi các chất không rõ nguồn gốc; không thực hiện nghi thức gây thương tích, cưỡng ép hoặc xâm phạm người khác.','Nếu dùng nến, đặt trên bề mặt an toàn, tránh vật dễ cháy và không để cháy khi không giám sát.'],['Tạo nghi thức phản tư','Chọn thời gian yên tĩnh, viết một điều muốn buông bỏ và một hành động nhỏ để chăm sóc bản thân. Sau đó đánh giá cảm xúc của mình.','Bạn luôn có thể dừng lại nếu thấy không thoải mái. Đây là hoạt động phản tư, không phải lời hứa về kết quả siêu nhiên.']],question:'Nguyên tắc quan trọng khi thực hành nghi thức là gì?',options:['Dùng chất không rõ nguồn gốc','Ép người khác tham gia','An toàn và tôn trọng sự đồng thuận','Bỏ qua mọi rủi ro'],answer:2,explain:'Luôn ưu tiên an toàn, sự đồng thuận và tôn trọng bối cảnh văn hóa.'},
{id:'thuc-hanh-bua',name:'Bùa chú: thực hành an toàn',cat:'Nghi thức',icon:'✹',color:'linear-gradient(135deg,#73504f,#2e2232)',desc:'Tìm hiểu bùa chú dân gian và tạo vật nhắc nhở mang ý nghĩa cá nhân.',level:'Cơ bản',lessons:[['Bùa chú trong đời sống','Bùa chú là những thực hành và vật mang biểu tượng gắn với niềm tin trong nhiều cộng đồng. Tên gọi, cách sử dụng và ý nghĩa thay đổi theo văn hóa và truyền thống.','Không có bằng chứng bảo đảm một vật hoặc câu chú tạo ra tác động siêu nhiên; hãy phân biệt tín ngưỡng với thông tin có thể kiểm chứng.'],['Chuẩn bị và ý định','Một cách thực hành phản tư không gắn với một truyền thống cụ thể là chuẩn bị giấy, bút, một khoảng không yên tĩnh và xác định điều bạn muốn nhắc nhở bản thân.','Tập trung vào hành động nằm trong khả năng của mình; không dùng nghi thức để kiểm soát hoặc ép buộc người khác.'],['Làm thẻ ý định','Bước 1: Viết một câu nhắc nhở tích cực, chẳng hạn “Tôi sẽ dành thời gian nghỉ ngơi”. Bước 2: Vẽ một hình đơn giản tự sáng tạo. Bước 3: Ghi một hành động có thể thực hiện. Bước 4: Giữ thẻ ở nơi an toàn và xem lại sau vài ngày.','Đây là thẻ nhắc nhở cá nhân, không phải bùa truyền thống hay bảo đảm hiệu lực. Không sử dụng ký hiệu thiêng của cộng đồng khác khi chưa hiểu và được phép.'],['An toàn và trách nhiệm','Không uống, bôi hoặc đốt vật liệu lạ; không dùng máu, chất gây hại, động vật hoặc các nghi thức gây thương tích. Luôn tôn trọng đồng thuận và quyền riêng tư.','Nếu có vấn đề sức khỏe, pháp lý hay tài chính, hãy tham khảo người có chuyên môn thay vì dựa vào bùa chú.']],question:'Thẻ ý định cá nhân nên được sử dụng như thế nào?',options:['Đảm bảo kết quả siêu nhiên','Nhắc mình về một hành động thực tế','Thay thế điều trị y tế','Ép người khác hành động'],answer:1,explain:'Thẻ ý định là vật nhắc nhở cá nhân, không bảo đảm hiệu quả siêu nhiên hay thay thế tư vấn chuyên môn.'},
{id:'linh-phu',name:'Linh phù & biểu tượng',cat:'Nghi thức',icon:'❖',color:'linear-gradient(135deg,#79553b,#332333)',desc:'Khám phá ý nghĩa văn hóa của phù và tạo biểu tượng cá nhân an toàn.',level:'Cơ bản',lessons:[['Linh phù là gì?','Linh phù hoặc phù là tên gọi chung cho các hình thức ký hiệu, văn tự và biểu tượng trong một số truyền thống tín ngưỡng; hình thức và ý nghĩa không giống nhau giữa các hệ.','Tài liệu và cách truyền dạy khác nhau. Không coi một ký hiệu sưu tầm trên mạng là phù xác thực hoặc đảm bảo hiệu lực.'],['Nguồn gốc và sự tôn trọng','Tìm hiểu người tạo, ngôn ngữ, bối cảnh và quy tắc sử dụng của biểu tượng trước khi học. Một số ký hiệu có thể gắn với thực hành tôn giáo hoặc cộng đồng cụ thể.','Không sao chép biểu tượng thiêng một cách tùy tiện và không giả nhận đại diện cho một truyền thống.'],['Tạo biểu tượng phản tư','Bước 1: Chọn một ý định lành mạnh. Bước 2: Dùng giấy và bút tạo hình tròn, đường thẳng hoặc hoa văn tự nghĩ ra. Bước 3: Viết một câu nhắc nhở và một hành động nhỏ. Bước 4: Ghi ngày để xem lại.','Hình tự vẽ là biểu tượng cá nhân, không được gọi là linh phù truyền thống đã chứng thực.'],['Bảo quản và giới hạn','Giữ biểu tượng ở nơi khô ráo, an toàn; có thể tái chế giấy khi không dùng. Tránh đốt trong không gian kín hoặc dùng chất không rõ nguồn gốc.','Không dùng biểu tượng thay cho chăm sóc y tế và không hứa hẹn kết quả vượt khả năng kiểm chứng.']],question:'Khi học về linh phù, điều nào phù hợp?',options:['Tự khẳng định mọi ký hiệu đều linh nghiệm','Tôn trọng nguồn gốc và không hứa hẹn hiệu lực','Sử dụng ký hiệu thiêng mà không cần tìm hiểu','Dùng vật liệu không rõ nguồn gốc'],answer:1,explain:'Nên tìm hiểu nguồn gốc, tôn trọng truyền thống và không khẳng định hiệu lực siêu nhiên.'},
{id:'phong-thuy',name:'Phong thủy nhập môn',cat:'Chiêm nghiệm',icon:'⌂',color:'linear-gradient(135deg,#5b6250,#292831)',desc:'Tìm hiểu phong thủy và quan sát không gian sống một cách thực tế.',level:'Cơ bản',lessons:[['Khái niệm phong thủy','Phong thủy là tập hợp các quan niệm truyền thống về mối liên hệ giữa con người và môi trường, với nhiều trường phái và cách ứng dụng.','Những dự đoán vận may không phải kết luận khoa học. Ưu tiên thiết kế có bằng chứng và nhu cầu thực tế của người sử dụng.'],['Quan sát không gian','Ghi nhận hướng nắng, ánh sáng, thông gió, độ ẩm, lối đi và các nguồn gây mất tập trung. Xem xét nhu cầu của mọi người cùng sử dụng không gian.','Đo và quan sát thực tế trước khi thay đổi; không đặt vật cản trước lối thoát hiểm.'],['Sắp xếp và an toàn','Bắt đầu bằng những việc dễ kiểm tra: dọn lối đi, bố trí ánh sáng đủ dùng, giảm độ ẩm và đảm bảo an toàn điện. Những thay đổi lớn cần xét ngân sách và kết cấu.','Không tự sửa kết cấu, điện hoặc hệ thống phòng cháy nếu thiếu chuyên môn; tham khảo người có chuyên môn.'],['Thực hành đánh giá phòng','Chọn một phòng, ghi lại một điểm thuận tiện và một điểm cần cải thiện. Chọn một điều chỉnh nhỏ, đo hoặc chụp lại trước và sau khi thực hiện.','Đánh giá theo mức độ thoải mái và an toàn thực tế, không theo lời hứa chắc chắn về vận mệnh.']],question:'Điều nào nên được ưu tiên khi sắp xếp không gian?',options:['Chặn lối thoát hiểm','Bỏ qua ánh sáng và thông gió','An toàn, nhu cầu sử dụng và điều kiện thực tế','Tin rằng một thay đổi đảm bảo giàu có'],answer:2,explain:'An toàn, ánh sáng, thông gió và nhu cầu sử dụng cần được ưu tiên.'},
{id:'bat-quai',name:'Bát quái căn bản',cat:'Chiêm nghiệm',icon:'☯',color:'linear-gradient(135deg,#69513d,#282332)',desc:'Học tám quái, cách đọc ba hào và liên hệ với Kinh Dịch.',level:'Cơ bản',lessons:[['Âm dương và hào','Một hào dương thường được biểu diễn bằng nét liền; một hào âm bằng nét đứt. Ba hào xếp chồng tạo nên một quái.','Đọc cấu trúc từ hào dưới lên. Âm và dương là các khái niệm tương quan, không đơn giản là tốt và xấu.'],['Tám quái cơ bản','Bát quái gồm Càn, Khôn, Chấn, Tốn, Khảm, Ly, Cấn và Đoài. Các quái thường gắn với hình ảnh trời, đất, sấm, gió, nước, lửa, núi và đầm.','Một số cách sắp xếp và diễn giải khác nhau giữa các truyền thống. Phân biệt tên quái với vị trí phương hướng trong từng đồ hình.'],['Từ quái đến quẻ','Một quẻ sáu hào có thể được xem là quái dưới và quái trên. Tám lựa chọn cho mỗi phần tạo nên 8 × 8 = 64 tổ hợp.','Không phải rút một quái ba hào là đã có một quẻ sáu hào; cần xác định đủ quái trên và quái dưới.'],['Thực hành nhận diện','Vẽ ba hào từ dưới lên. Nếu cả ba là dương, đó là Càn; nếu cả ba là âm, đó là Khôn. Thử đối chiếu các tổ hợp còn lại với bảng Bát quái.','Ghi nguồn và thứ tự đọc khi tra cứu; không gán ý nghĩa chắc chắn cho quyết định quan trọng.']],question:'Một quái trong Bát quái được tạo từ bao nhiêu hào?',options:['Hai hào','Ba hào','Sáu hào','Tám hào'],answer:1,explain:'Một quái có ba hào; hai quái có thể kết hợp thành quẻ sáu hào.'},
{id:'lo-ban-sat',name:'Bùa Lỗ Ban – Sát',cat:'Nghi thức',icon:'✵',color:'linear-gradient(135deg,#705245,#302232)',desc:'Tìm hiểu tài liệu Lỗ Ban Sát, nghi thức, linh phù và giới hạn an toàn.',level:'Cơ bản',sourceUrl:'https://www.studocu.vn/vn/document/truong-trung-hoc-co-so/toan-6/789921367-bua-lo-ban-sat/169239170',lessons:[['Tổng quan tài liệu Lỗ Ban Sát','Tài liệu được cung cấp có tiêu đề Bùa Lỗ Ban Sát; phần đầu mang tên Lỗ Ban Núi Cấm. Mục lục liệt kê nhiều nhóm nội dung, từ niệm hương, luyện phép và họa phù đến cầu tài, trừ tà và trấn trạch. Đây là một tài liệu được đăng bởi người dùng, không phải nguồn đã được xác minh độc lập.','Bản xem trực tuyến chỉ cho tiếp cận phần đầu và một số đoạn trích; không thể xác minh đầy đủ toàn bộ nội dung sách hoặc tính đại diện của nó cho mọi truyền thống.'],['Niệm hương và thỉnh tổ','Ở phần đầu, tài liệu mô tả việc niệm hương, lời thỉnh tổ và quán tưởng linh phù trong một bối cảnh nghi lễ; tác giả nhắc đến một số giờ truyền thống và các đợt luyện tập được tính bằng ngày.','Đây là mô tả niềm tin trong tài liệu, không phải bằng chứng về hiệu lực của nghi lễ. Hãy tôn trọng tính đa dạng của các cộng đồng và cách thực hành.'],['Luyện phép và quán tưởng','Các mục luyện phép trình bày sự kết hợp giữa chú nguyện, quán tưởng và quá trình lặp lại theo thời gian. Phần được xem có nhắc đến những số lần và số ngày khác nhau tùy nội dung, không cho phép suy ra một quy tắc chung duy nhất.','Một số chỉ dẫn trong nguồn có rủi ro: không nhìn trực tiếp mặt trời, không uống nước phù hoặc chất không rõ thành phần; không dùng hương, nến thiếu giám sát.'],['Khai bút, các chủ đề và giới hạn','Mục lục và phần xem trước đề cập đến khai bút họa phù, sắt thủy, hộ thân, trừ tà, cầu tài và trấn bằng Bát quái. Đây là cách các chủ đề được trình bày trong nguồn, không phải xác nhận công dụng.','Không xem các tuyên bố chữa bệnh là lời khuyên y tế. Tôn trọng quyền riêng tư, đồng thuận và luật pháp; không dùng nghi thức để đe dọa hoặc gây tổn hại người khác.']],sections:[[{title:'Phạm vi và xuất xứ',text:'Nguồn là bản đăng trên Studocu do người dùng chia sẻ. Trang hiển thị mục lục nhiều chương và một phần nội dung; tác giả, niên đại và xuất xứ đầy đủ chưa được kiểm chứng.'},{title:'Cách đọc tài liệu',text:'Phân biệt tên chương, lời kể của tài liệu và hiệu lực được khẳng định. Ghi nguồn và số mục khi ghi chép; không xem mọi điều được nêu là sự thật đã xác lập.'},{title:'Thực hành học tập',text:'Chọn ba mục trong mục lục như niệm hương, họa phù, trấn Bát quái. Viết một câu về chủ đề của từng mục và đánh dấu mục nào chưa đọc được toàn văn.'}],[{title:'Những thành phần được nhắc đến',text:'Đoạn xem trước kết hợp lời niệm, việc thỉnh tổ, nhang và quán tưởng. Đây là mô tả về nghi thức theo tài liệu, không phải yêu cầu mọi người phải làm theo.'},{title:'Nhịp luyện được mô tả',text:'Nguồn nêu các giờ Tý, Ngọ, Mão, Dậu và những khoảng thời gian luyện tập khác nhau; các con số thể hiện quy ước trong văn bản, không chứng minh tác dụng.'},{title:'Gợi ý thực hành an toàn',text:'Thay vì thực hiện nghi thức, hãy viết một đoạn tóm tắt về vai trò của lời niệm và quán tưởng trong văn bản. Nếu dùng nhang hoặc nến, cần giám sát, thông gió và bảo đảm phòng cháy.'}],[{title:'Luyện và quán tưởng',text:'Phần đầu mô tả việc nhắc lại lời niệm và hình dung biểu tượng qua thời gian; văn bản coi thầy và tổ là những yếu tố quan trọng trong cách truyền dạy.'},{title:'Không thực hiện chỉ dẫn có hại',text:'Nguồn có nhắc nhìn mặt trời và uống nước phù. Nhìn trực tiếp mặt trời có thể gây tổn thương mắt; không uống nước hoặc vật liệu không rõ độ an toàn.'},{title:'Bài tập ghi chép',text:'Lập hai cột: “tác giả mô tả” và “điều cần kiểm chứng”. Ghi lại một tuyên bố của nguồn bằng lời của bạn, rồi nêu cách tiếp cận an toàn hơn.'}],[{title:'Các chủ đề xuất hiện trong nguồn',text:'Mục lục gọi tên khai bút họa linh phù, hộ thân, trừ tà, chiêu tài và trấn Bát quái. Chỉ phần xem trước được dùng để mô tả; những chương chưa đọc toàn văn cần ghi là chưa xác minh.'},{title:'Phân biệt tín ngưỡng và điều trị',text:'Một số tiêu đề và đoạn trích đề cập chữa bệnh; không có cơ sở để bảo đảm điều đó. Khi có triệu chứng hoặc cần điều trị, hãy tìm nhân viên y tế có chuyên môn.'},{title:'Thực hành an toàn',text:'Chọn một chủ đề bạn muốn nghiên cứu và ghi nguồn. Bạn có thể tự vẽ biểu tượng hình học đơn giản như bài tập phản tư, nhưng không nên gọi đó là bản sao linh phù trong sách.'}]],question:'Khi đọc tài liệu Bùa Lỗ Ban Sát, cách tiếp cận nào phù hợp?',options:['Nhìn trực tiếp mặt trời để luyện tập','Uống nước phù thay cho điều trị','Phân biệt mô tả tín ngưỡng và bằng chứng; ưu tiên an toàn','Khẳng định mọi phép trong nguồn chắc chắn có hiệu lực'],answer:2,explain:'Đọc có phê phán, tôn trọng tín ngưỡng, tránh các chỉ dẫn gây hại và không thay thế chăm sóc y tế.'}
];
