  'lenormand':['Những biểu tượng này gợi mình nhìn lại điều gì trong kế hoạch sắp tới?','Mình nên cân nhắc khía cạnh nào trước một lựa chọn?'],
  'oracle':['Mình cần lời nhắc nào để chăm sóc bản thân hôm nay?','Điều gì có thể giúp mình bình tĩnh hơn trong tuần này?'],
  'bai-tay':['Mình nên chú ý điều gì khi chuẩn bị cho công việc mới?','Mình có thể nhìn nhận chuyện tình cảm theo góc độ nào khác?'],
  'tu-vi':['Mình có thể suy ngẫm gì về bản thân qua cung Mệnh?','Lĩnh vực của cung mình chọn đang cần mình quan tâm điều gì?'],
